(()=>{
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const yearOf=i=>String(i.payload.year||(i.due_at||i.created_at||'').slice(0,4)||new Date().getFullYear());
  const average=items=>items.length?items.reduce((n,i)=>n+Number(i.payload.score)*Number(i.payload.weight||1),0)/items.reduce((n,i)=>n+Number(i.payload.weight||1),0):null;
  function rows(data,filter){
    const grouped=new Map();
    for(const i of data.items.filter(i=>['grade','attendance'].includes(i.kind)&&(!filter.student||i.student_id===filter.student)&&yearOf(i)===filter.year&&String(i.payload.period)===filter.period)){
      const key=JSON.stringify([i.student_id,i.payload.subject.trim().toLocaleLowerCase('pt-BR')]);if(!grouped.has(key))grouped.set(key,{student:i.student_id,subject:i.payload.subject,grades:[],attendance:[]});grouped.get(key)[i.kind==='grade'?'grades':'attendance'].push(i);
    }
    return [...grouped.values()].map(r=>({...r,partial:average(r.grades.filter(i=>i.payload.component!=='final')),final:average(r.grades),lessons:r.attendance.reduce((n,i)=>n+i.payload.lessons,0),absences:r.attendance.reduce((n,i)=>n+i.payload.absences,0)})).sort((a,b)=>a.student.localeCompare(b.student)||a.subject.localeCompare(b.subject,'pt-BR'));
  }
  function render(data,filter){
    const year=String(data.selectedClass?.academic_year||new Date().getFullYear()),years=[...new Set([year,...data.items.filter(i=>['grade','attendance'].includes(i.kind)).map(yearOf)])].sort().reverse();if(!years.includes(filter.year))filter.year=year;
    if(!['1','2','3','4'].includes(filter.period))filter.period=String(Math.ceil((new Date().getMonth()+1)/3));
    const dropdown=(label,key,values)=>`<div><label for="report-${key}">${label}</label><select id="report-${key}" data-report-filter="${key}">${values.map(([id,text])=>`<option value="${esc(id)}" ${filter[key]===id?'selected':''}>${esc(text)}</option>`).join('')}</select></div>`;
    const controls=dropdown('Aluno','student',[['','Todos os alunos'],...data.students.map(a=>[a.id,a.name+(a.login?' · '+a.login:'')])])+dropdown('Ano letivo','year',years.map(y=>[y,y]))+dropdown('Período','period',[1,2,3,4].map(n=>[String(n),n+'º bimestre']));
    const pass=Number(data.institution?.pass_grade??6),frequency=Number(data.institution?.attendance_min??75),num=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),cell=(n,reference=true)=>n===null?'<td class="report-missing">—</td>':`<td class="${reference&&n<pass?'report-low':''}">${num(n)}</td>`;
    const result=rows(data,filter),name=id=>data.students.find(a=>a.id===id)?.name||'Aluno';
    return `<section class="school-card report-card"><div class="report-heading"><div><h2>Notas e faltas unificadas</h2><p>Boletim por disciplina · ${esc(data.selectedClass?.name||'Turma')}</p></div><span class="school-pill">${filter.year} · ${filter.period}º bimestre</span></div><div class="grade-filters">${controls}</div><div class="report-scroll" tabindex="0" role="region" aria-label="Boletim com rolagem horizontal"><table class="report-table"><caption>Notas, médias e frequência do período selecionado</caption><thead><tr>${!filter.student?'<th>Aluno</th>':''}<th>Disciplina</th><th>N1</th><th>N2</th><th>Prova integrada</th><th>Participação</th><th>Substitutiva</th><th>Outras avaliações</th><th>Média parcial</th><th>Avaliação final</th><th>Média final</th><th>Faltas acumuladas</th><th>Limite de faltas</th><th>Total de aulas</th><th>Acompanhamento</th></tr></thead><tbody>${result.length?result.map(r=>{const cells=['n1','n2','integrated','participation','substitute','other'].map(component=>cell(average(r.grades.filter(i=>(i.payload.component||'other')===component)))).join(''),lowFrequency=r.lessons>0&&100*(r.lessons-r.absences)/r.lessons<frequency;return `<tr>${!filter.student?`<td>${esc(name(r.student))}</td>`:''}<th scope="row">${esc(r.subject)}</th>${cells}${cell(r.partial)}${cell(average(r.grades.filter(i=>i.payload.component==='final')))}${cell(r.final)}<td class="${lowFrequency?'report-low':''}">${r.lessons?r.absences:'—'}</td><td>${r.lessons?Math.floor(r.lessons*(100-frequency)/100):'—'}</td><td>${r.lessons||'—'}</td><td>${lowFrequency?'Atenção à frequência':r.final===null?'Sem notas':r.final<pass?'Abaixo da referência':'Média atingida'}</td></tr>`;}).join(''):`<tr><td colspan="${filter.student?14:15}" class="report-empty">Nenhum lançamento para este aluno e período.</td></tr>`}</tbody></table></div><p class="school-help">Traço significa sem lançamento; zero é uma nota registrada. As médias usam os pesos informados nas avaliações. A média parcial desconsidera a avaliação final; a média final inclui todas as notas do período. Substitutivas entram com seu peso, sem substituir automaticamente outra nota.</p><p class="school-help">Referências da escola: média ${num(pass)} e frequência mínima ${num(frequency)}%. O limite de faltas considera as aulas efetivamente lançadas. O boletim apresenta acompanhamento, sem decidir aprovação automática.</p></section>`;
  }
  window.ConectaReportCard={render,rows,yearOf};
})();
